#!/usr/bin/env python3
import base64
from pathlib import Path
path = Path('utils/supabaseRealtimeService.ts')
text = path.read_text()
NEW_BLOCK = base64.b64decode("""""").decode()
old_markers = [
    '// ==================== RECORDATORIOS (localStorage - Supabase schema cache issue) ====================',
    '// ==================== RECORDATORIOS (Supabase) ====================',
]
start = None
for m in old_markers:
    if m in text:
        start = text.index(m)
        break
if start is None:
    raise SystemExit('reminders section marker not found')
end = text.index('// ==================== CASAS ====================')
path.write_text(text[:start] + NEW_BLOCK + text[end:])
final = path.read_text()
assert "from('reminders')" in final
assert 'localStorage - Supabase schema cache issue' not in final
print('service reminders patched', path.stat().st_size)
